import requests
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
r=requests.get(u,params={'db':'pubmed','term':'(EZH2 OR enhancer of zeste homolog 2) AND (IPMN OR intraductal papillary mucinous neoplasm) AND (p27 OR CDKN1B)','retmode':'json','retmax':10},timeout=20)
print('status',r.status_code)
data=r.json(); ids=data['esearchresult']['idlist']; print('ids',ids)
if ids:
 x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
 for i in ids: print(i,x[i].get('title'),x[i].get('pubdate'),x[i].get('fulljournalname'))
else: print('No PubMed matches')
